package main

import "fmt"

func appendLocally(values []int, value int) {
	values = append(values, value)
	fmt.Println("inside helper:", values)
}

func appendAndReturn(values []int, value int) []int {
	return append(values, value)
}

func main() {
	values := make([]int, 2, 3)
	values[0], values[1] = 1, 2

	appendLocally(values, 3)
	fmt.Println("caller still sees:", values)

	values = appendAndReturn(values, 3)
	fmt.Println("caller after assign:", values)
}
