```go
package main

import "fmt"

func squares(input []int) []int {
	out := make([]int, len(input))
	for i, n := range input {
		out[i] = n * n
	}
	return out
}

func positives(input []int) []int {
	out := make([]int, 0, len(input))
	for _, n := range input {
		if n > 0 {
			out = append(out, n)
		}
	}
	return out
}

func main() {
	values := []int{-2, 4, 0, 7}
	fmt.Println("squares:", squares(values))
	fmt.Println("positives:", positives(values))
}
